<template>
  <AppShell :key="state.language" :title="t('discoverCategories')" active="categories" edge>
    <view class="category-intro"><text class="section-title">{{ t('categoryIntro') }}</text><text class="muted">{{ t('categoryNote') }}</text></view>
    <view class="category-search"><button class="search-link" @click="go('search')"><LineIcon name="search" :size="19" /><text>{{ t('search') }}</text></button><button class="camera-link" :aria-label="t('photoSearch')" @click="go('photo')"><LineIcon name="camera" :size="21" /></button></view>
    <view class="category-tiles"><button v-for="category in categories" :key="category.id" :class="{ selected: active === category.id }" @click="active = category.id"><LineIcon :name="category.icon" :size="34" /><text class="category-name">{{ t(category.id) }}</text><text class="muted">{{ counts(category.id) }} {{ t('pieces') }}</text></button><button @click="go('catalog')"><LineIcon name="star" :size="34" /><text class="category-name">{{ t('browseEdit') }}</text><text class="muted">{{ t('selectedProducts') }}</text></button><button @click="go('catalog', { offers: 1 })"><LineIcon name="tag" :size="34" /><text class="category-name">{{ t('offers') }}</text><text class="muted">{{ text('أسعار مختارة', 'Selected prices') }}</text></button></view>
    <view class="category-panel"><view class="section-head"><view><text class="section-title">{{ t('shopCategory') }} {{ t(active) }}</text><text class="muted">{{ t('chooseType') }}</text></view><button class="text-button" @click="go('catalog', { category: active })">{{ t('viewAll') }}<LineIcon name="arrow" :size="15" :mirror="state.language === 'en'" /></button></view><view class="subcategories"><button v-for="item in subcategories" :key="item.subCategory || item.id" @click="item.subCategory ? go('catalog', { category: active, sub: item.subCategory }) : go('product', { id: item.id })"><image :src="item.images[0]" mode="aspectFill" /><text>{{ subName(item.subCategory) || productName(item) }}</text></button></view></view>
    <view class="category-curation"><view><text class="section-title">{{ t('curation') }}</text><text class="muted">{{ t('curationNote') }}</text><button class="text-button" @click="go('catalog')">{{ t('shop') }}</button></view><image src="/static/products/0.jpg" mode="aspectFill" /></view>
  </AppShell>
</template>
<script setup>
import { computed, ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import AppShell from '../../components/AppShell.vue'; import LineIcon from '../../components/LineIcon.vue'; import { state, go, refreshProducts } from '../../store.js'; import { t, text, productName } from '../../i18n.js';
const active = ref('clothes'); const categories = [{ id: 'clothes', icon: 'clothes' }, { id: 'bags', icon: 'bag' }, { id: 'shoes', icon: 'shoes' }, { id: 'accessories', icon: 'accessories' }];
const counts = id => state.products.filter(p => p.category === id).length;
const subcategories = computed(() => { const order = ['shirts', 'jackets', 'trousers', 'hoodies']; return [...new Map(state.products.filter(p => p.category === active.value).map(p => [p.subCategory || p.id, p])).values()].sort((a, b) => (order.indexOf(a.subCategory) < 0 ? 99 : order.indexOf(a.subCategory)) - (order.indexOf(b.subCategory) < 0 ? 99 : order.indexOf(b.subCategory))).slice(0, 6); });
const labels = { shirts: ['قمصان وبلوزات', 'Shirts & blouses'], jackets: ['جاكيتات', 'Jackets'], trousers: ['بناطيل', 'Trousers'], hoodies: ['ملابس مريحة', 'Relaxed pieces'], heels: ['أحذية بكعب', 'Heels'], sneakers: ['أحذية رياضية', 'Sneakers'], tophandle: ['حقائب يد', 'Top-handle bags'], shoulder: ['حقائب كتف', 'Shoulder bags'], earrings: ['أقراط', 'Earrings'], jewelry: ['مجوهرات', 'Jewellery'] };
const subName = id => labels[id] ? text(...labels[id]) : '';
onShow(() => refreshProducts().catch(() => {}));
</script>
